pub fn ht_create<'a>() -> *mut Ht<'a> {
    unsafe {
        let layout = Layout::new::<Ht<'a>>();
        let table = alloc(layout) as *mut Ht<'a>;
        if table.is_null() {
            return ptr::null_mut();
        }
        (*table).length = 0;
        (*table).capacity = 16;

        let entries_layout = Layout::array::<HtEntry<'a>>(16).unwrap();
        (*table).entries = alloc(entries_layout) as *mut HtEntry<'a>;
        if (*table).entries.is_null() {
            std::alloc::dealloc(table as *mut u8, layout);
            return ptr::null_mut();
        }
        table
