pub fn ht_destroy(table: *mut Ht) {
    unsafe {
        if table.is_null() {
            return;
        }
        for i in 0..(*table).capacity {
            let entry = (*table).entries.offset(i as isize);
            if !(*entry).key.is_null() {
                let key_ptr = (*entry).key as *mut c_void;
                ptr::drop_in_place(key_ptr);
            }
        }
        ptr::drop_in_place((*table).entries);
        ptr::drop_in_place(table);
    }
}

pub fn ht_get<'a>(table: &Ht<'a>, key: &str) -> *mut c_void {
    let hash = hash_key(key);
    let mut index = (hash & (table.capacity as u64 - 1)) as usize;
    while !table.entries.is_null() && unsafe { !(*table.entries.add(index)).key.is_null() } {
        if key == unsafe { (*table.entries.add(index)).key } {
            return unsafe { (*table.entries.add(index)).value };
        }
        index += 1;
        if index >= table.capacity {
            index = 0;
        }
    }
    ptr::null_mut()
}

pub fn ht_expand<'a>(table: &mut Ht<'a>) -> bool {
    let new_capacity = table.capacity * 2;
    if new_capacity < table.capacity {
        return false;
    }

    let new_entries = vec![HtEntry { key: "", value: ptr::null_mut() }; new_capacity].into_boxed_slice();
    let new_entries_ptr = Box::into_raw(new_entries) as *mut HtEntry<'a>;

    if new_entries_ptr.is_null() {
        return false;
    }

    unsafe {
        for i in 0..table.capacity {
            let entry = &*table.entries.add(i);
            if !entry.key.is_empty() {
                ht_set_entry(&mut *new_entries_ptr, new_capacity, entry.key, entry.value, None);
            }
        }

        Box::from_raw(table.entries);
    }

    table.entries = new_entries_ptr;
    table.capacity = new_capacity;
    true
}

pub fn ht_iterator<'a>(table: *mut Ht<'a>) -> Hti<'a> {
    Hti {
        key: "",
        value: std::ptr::null_mut(),
        _table: table,
        _index: 0,
    }
}

pub fn ht_next(it: &mut Hti) -> bool {
    unsafe {
        let table = &mut *it._table;
        while it._index < table.capacity {
            let i = it._index;
            it._index += 1;
            let entry = &mut *table.entries.add(i);
            if !entry.key.is_null() {
                it.key = entry.key;
                it.value = entry.value;
                return true;
            }
        }
    }
    false
}

