pub fn ht_set<'a>(table: &mut Ht<'a>, key: &'a str, value: *mut c_void) -> Option<&'a str> {
    assert!(!value.is_null(), "value != NULL");

    if table.length >= table.capacity / 2 {
        if !ht_expand(table) {
            return None;
        }
    }

    ht_set_entry(
        unsafe { std::slice::from_raw_parts_mut(table.entries, table.capacity) },
        table.capacity,
        key,
        value,
        Some(&mut table.length),
    )
}
